/** Drives the frame foil + pip colours (projects.css `.tc-type-*`). */
export type CardType = "web" | "tool" | "cli" | "supporter"
export type Rarity = "ssr" | "rare" | "supporter"
export type MoveCost = 1 | 2 | 3

export const LANGUAGES = [
  "TypeScript",
  "CSS",
  "JavaScript",
  "Nix",
  "Swift",
  "Vue",
  "Rust",
  "Shell",
  "Lua",
] as const
export type Language = (typeof LANGUAGES)[number]
export type LanguageShare = { language: Language | "Other"; percent: number }

export type CardLink =
  | { kind: "enter"; route: PageRoute }
  | { kind: "repo" | "website" | "profile" | "prs"; href: string }

export type ProjectCard = {
  id: ProjectCardId
  name: string
  type: CardType
  rarity: Rarity
  /** Set code printed on the card, e.g. "KF 001/004". */
  setCode: string
  image: StaticImageData
  /** The big number on the back (D1 "hero" stat). */
  hero: { value: number; unit: "commits" | "upstreamPrs" }
  languages: readonly LanguageShare[]
  moves: readonly { id: MoveId; cost: MoveCost }[]
  links: readonly CardLink[]
}

function isLanguage(value: string): value is Language {
  return LANGUAGES.some((language) => language === value)
}

/**
 * Byte counts (GitHub /languages) → the top `max` shares as percentages, with
 * everything else (and any language we have no icon for) folded into
 * "Other". Rounded to one decimal; empty input gives no shares.
 */
export function languageShares(
  bytes: Readonly<Record<string, number>>,
  max = 3
): LanguageShare[] {
  const total = Object.values(bytes).reduce((sum, n) => sum + n, 0)
  if (total <= 0) return []
  const known: LanguageShare[] = []
  let other = 0
  for (const [name, n] of Object.entries(bytes).sort((a, b) => b[1] - a[1])) {
    const percent = (n / total) * 100
    if (isLanguage(name) && known.length < max)
      known.push({ language: name, percent })
    else other += percent
  }
  const round = (n: number) => Math.round(n * 10) / 10
  const shares = known.map((share) => ({
    ...share,
    percent: round(share.percent),
  }))
  return other > 0
    ? [...shares, { language: "Other", percent: round(other) }]
    : shares
}

