/** Live numbers behind the Supporter card (also used by the move demos). */
export const CONTRIBUTIONS = stats.contributions

/**
 * Values for the `{placeholders}` in the move copy (about.projects.moves),
 * so the numbers come from the generated stats and the WebMCP registry
 * rather than being typed into both dictionaries.
 */
export function moveVars(
  locale: Locale
): Readonly<Record<string, string | number>> {
  const packages = CONTRIBUTIONS.nixpkgsMaintained
  return {
    count: packages.length,
    packages: new Intl.ListFormat(locale, { type: "conjunction" }).format(
      packages
    ),
    prs: CONTRIBUTIONS.nixpkgsMergedPRs,
    tools: WEBMCP_TOOL_NAMES.length,
    upstream: CONTRIBUTIONS.upstreamMergedPRs,
  }
}

/**
 * The order cards turn face up after the pack is torn: hand order, with the
 * SSR held back to land last (the payoff).
 */
export function revealOrder(order: readonly ProjectCardId[]): ProjectCardId[] {
  return [
    ...order.filter((id) => PROJECT_CARDS[id].rarity !== "ssr"),
    ...order.filter((id) => PROJECT_CARDS[id].rarity === "ssr"),
  ]
}

/** Fan order: in "featured" layout the SSR sits second (front-centre). */
export const DEFAULT_CARD_ORDER: readonly ProjectCardId[] = [
  "neomouse",
  "desktop",
  "helloWorldPp",
  "supporter",
]

/**
 * A persisted card order (localStorage, untrusted) → a valid permutation;
 * see lib/card-order for the rules.
 */
export function parseCardOrder(value: unknown): ProjectCardId[] {
  return parseOrder(value, DEFAULT_CARD_ORDER)
}
